({
async verifyAttachment(tab,id){const h=eval(load("helpers"));const v=await h.ev(tab,"({text:document.body.innerText,links:[...document.querySelectorAll('a')].filter(a=>a.innerText==='View your resume').map(a=>a.href)})");if(!v.text.includes("Your resume has been updated!")||!v.links[0])throw Error("Resume update unconfirmed");const code="import hashlib,json,urllib.request;from pathlib import Path;p=Path('job-search/applications/"+id+"');url="+JSON.stringify(v.links[0])+";data=urllib.request.urlopen(url,timeout=30).read();actual=hashlib.sha256(data).hexdigest();assert actual==json.loads((p/'verification.json').read_text())['sha256'];(p/'Wellfound_attached_CV.pdf').write_bytes(data);(p/'upload-verification.json').write_text(json.dumps({'board':'Wellfound','sha256':actual,'bytes':len(data),'matches_reviewed_pdf':True,'attachment_path':url.split('?')[0],'upload_confirmation':'Your resume has been updated!'},indent=2)+'\\n');print('Attachment hash verified')";const r=await tools.exec_command({cmd:"python3 -c "+h.q(code),max_output_tokens:100});if(r.exit_code!==0)throw Error(r.output);text(r.output);},
async fillMessage(tab,message){const h=eval(load("helpers"));return h.ev(tab,"(()=>{const e=document.querySelector('textarea');if(!e)throw Error('No application field');e.focus();Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(e,"+JSON.stringify(message)+");e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));e.blur();return {name:e.name,value:e.value}})()");},
async recordReceipt(tab,id){const h=eval(load("helpers"));const c=await h.ev(tab,"({url:location.href,text:document.body.innerText})");if(!c.text.includes("SUCCESS! YOUR APPLICATION HAS BEEN SENT.")){store("wfLastReceiptCheck",{tab,id,...c});text("Awaiting explicit Wellfound receipt");return false;}await h.save("job-search/applications/"+id+"/confirmation.json",{status:"submitted",round:"jobboards-2026-10-09",submitted_on:"2026-10-12",in_scope:true,browser:"Connected native T3, saved default Brave",...c});text(await tools.exec_command({cmd:".venv/bin/python scripts/record-jobboard-result.py "+h.q(id),max_output_tokens:150}));return true;}
})
